      { mealType: "Breakfast", name: "Tofu Scramble", time: "15 min", macros: "20p / 16c / 10f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["14 oz firm tofu, pressed and crumbled", "1 tsp turmeric", "1 tsp garlic powder", "1 tsp onion powder", "2 tbsp nutritional yeast", "½ cup diced bell peppers", "½ cup cherry tomatoes", "1 tsp olive oil", "Salt and pepper"], instructions: ["Heat oil in skillet; add peppers, cook 3 min.", "Add crumbled tofu and all spices; stir-fry 5–7 min.", "Add tomatoes; cook 2 min more.", "Serve with toast or in a wrap."], tip: "Nutritional yeast adds a cheesy flavor and B12 — crucial for plant-based diets." },
      { mealType: "Breakfast", name: "Almond Butter Banana Smoothie", time: "5 min", macros: "14p / 48c / 12f", dietary: ["GF", "DF", "SF", "Vegan"], ingredients: ["1 frozen banana", "2 tbsp almond butter", "1 scoop plant-based protein powder", "1 cup oat milk", "1 tbsp flaxseeds", "Ice cubes"], instructions: ["Blend all until smooth.", "Serve immediately."], tip: "Flaxseeds add omega-3s, fiber, and a mild nutty flavor." },
      { mealType: "Lunch", name: "Lentil & Vegetable Soup", time: "35 min", macros: "18p / 48c / 4f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["1 cup red lentils, rinsed", "1 can (14 oz) diced tomatoes", "2 cups vegetable broth", "1 carrot, diced", "2 celery stalks, diced", "1 onion, diced", "2 garlic cloves, minced", "1 tsp cumin", "1 tsp turmeric", "Juice of 1 lemon"], instructions: ["Sauté onion, carrot, celery, and garlic 5 min.", "Add lentils, tomatoes, broth, and spices. Simmer 20–25 min.", "Stir in lemon juice. Serve with crusty bread."], tip: "Lentils pack 18g of protein per cup and are one of the most iron-rich plant foods." },
      { mealType: "Lunch", name: "Black Bean & Corn Burrito Bowl", time: "15 min", macros: "16p / 58c / 10f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["1 can (15 oz) black beans, drained", "¾ cup cooked brown rice", "½ cup frozen corn, thawed", "½ cup salsa", "¼ avocado, sliced", "¼ cup red onion, diced", "Lime juice", "Cilantro"], instructions: ["Warm beans and rice.", "Bowl: rice, beans, corn, red onion, salsa.", "Top with avocado, lime juice, and cilantro."], tip: "Add a scoop of hemp hearts (3 tbsp = 10g protein) to boost the protein total." },
      { mealType: "Lunch", name: "Roasted Chickpea Buddha Bowl", time: "30 min", macros: "18p / 52c / 14f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["1 can (15 oz) chickpeas, drained and dried", "1 tsp olive oil", "1 tsp paprika", "1 tsp cumin", "¾ cup cooked quinoa", "1 cup roasted beets", "1 cup arugula", "2 tbsp tahini drizzle", "Lemon juice"], instructions: ["Toss chickpeas with oil and spices; roast at 425°F for 25–30 min.", "Build bowl with quinoa, arugula, beets, and chickpeas.", "Drizzle with tahini and lemon juice."], tip: "Roasting chickpeas gives them a satisfying crunch that rivals croutons." },
      { mealType: "Dinner", name: "Mushroom & Lentil Bolognese", time: "35 min", macros: "20p / 62c / 8f", dietary: ["DF", "NF", "SF", "Vegan"], ingredients: ["1 cup green lentils", "2 cups mushrooms, finely chopped", "1 can (14 oz) crushed tomatoes", "½ onion, diced", "3 garlic cloves, minced", "1 tsp olive oil", "1 tsp Italian seasoning", "3 oz whole wheat spaghetti (dry)", "Fresh basil"], instructions: ["Cook lentils; drain.", "Sauté onion and garlic 3 min; add mushrooms, cook 5 min.", "Add tomatoes, lentils, and seasoning; simmer 10 min.", "Serve over cooked spaghetti with fresh basil."], tip: "Mushrooms mimic ground meat texture — nobody will miss the beef." },
      { mealType: "Dinner", name: "Thai Peanut Tempeh Bowl", time: "25 min", macros: "28p / 44c / 18f", dietary: ["GF", "DF", "SF", "Vegan"], ingredients: ["8 oz tempeh, cubed", "¾ cup cooked brown rice", "1 cup broccoli, steamed", "1 cup shredded purple cabbage", "Thai peanut sauce: 3 tbsp peanut butter, 2 tbsp soy sauce, 1 tbsp lime juice, 1 tsp honey, 1 tsp ginger, water to thin"], instructions: ["Pan-fry tempeh cubes in a little oil until golden, 8–10 min.", "Whisk peanut sauce ingredients.", "Build bowl with rice, broccoli, cabbage, and tempeh.", "Drizzle with peanut sauce."], tip: "Tempeh is fermented soy with 31g protein per cup — more than chicken by weight." },
      { mealType: "Dinner", name: "Stuffed Portobello Mushrooms", time: "30 min", macros: "14p / 32c / 12f", dietary: ["GF", "DF", "NF", "Vegan"], ingredients: ["4 large portobello caps", "1 cup cooked quinoa", "1 can (15 oz) white beans, drained", "½ cup sundried tomatoes", "2 garlic cloves, minced", "1 tsp Italian herbs", "2 tbsp olive oil", "Fresh parsley"], instructions: ["Preheat oven to 400°F. Brush mushroom caps with oil.", "Mix quinoa, beans, tomatoes, garlic, and herbs.", "Fill each cap with mixture; bake 20 min.", "Garnish with parsley."], tip: "White beans are a complete protein when combined with quinoa in this dish." },
      { mealType: "Snack", name: "Edamame with Sea Salt", time: "5 min", macros: "17p / 14c / 8f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["1½ cups frozen edamame in pods", "Sea salt", "Optional: sesame oil drizzle, chili flakes"], instructions: ["Microwave edamame per package (about 4 min).", "Sprinkle with sea salt and optional toppings."], tip: "Edamame is one of the few plant foods with all 9 essential amino acids." },
      { mealType: "Snack", name: "Avocado & Tomato on Rice Cakes", time: "5 min", macros: "4p / 20c / 12f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["2 plain rice cakes", "½ avocado, mashed", "1 small tomato, sliced", "Red pepper flakes", "Lemon juice", "Salt and pepper"], instructions: ["Mash avocado with lemon juice, salt, and pepper.", "Spread on rice cakes; top with tomato slices.", "Sprinkle red pepper flakes."], tip: "A crispy, low-calorie alternative to avocado toast." }
