      { mealType: "Breakfast", name: "6-Egg Scramble with Whole Wheat Toast", time: "12 min", macros: "42p / 36c / 20f", dietary: ["NF", "SF"], ingredients: ["3 whole eggs + 3 egg whites", "1 oz shredded cheese", "¼ cup diced onion and peppers", "2 slices whole wheat toast", "1 tsp butter", "Salt and pepper"], instructions: ["Whisk eggs and egg whites together.", "Sauté onion and peppers in butter 2 min.", "Add eggs; stir gently over medium heat until just set.", "Add cheese; fold and serve with toast."], tip: "Whole eggs provide testosterone-supporting fats — don't fear the yolk for mass building." },
      { mealType: "Breakfast", name: "Mass Builder Smoothie", time: "5 min", macros: "50p / 70c / 15f", dietary: ["GF", "SF"], ingredients: ["2 scoops chocolate protein powder", "1 cup whole milk", "1 cup oat milk", "1 frozen banana", "2 tbsp peanut butter", "1 tbsp honey", "¼ cup rolled oats", "Ice"], instructions: ["Blend everything until smooth.", "Drink within 30 min of waking for maximum nutrient uptake."], tip: "1000+ calorie meal in a glass — perfect for hardgainers who struggle to eat enough." },
      { mealType: "Lunch", name: "Double Chicken Rice Bowl", time: "25 min", macros: "60p / 65c / 14f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["12 oz grilled chicken breast", "1½ cups cooked white rice", "1 cup roasted broccoli", "½ cup black beans", "3 tbsp teriyaki sauce", "Sesame seeds"], instructions: ["Grill chicken; slice into strips.", "Mix rice with black beans.", "Top with chicken and broccoli.", "Drizzle teriyaki sauce; garnish with sesame seeds."], tip: "White rice absorbs into muscle faster than brown — ideal for post-workout bulking meals." },
      { mealType: "Lunch", name: "Steak & Potato Performance Plate", time: "25 min", macros: "45p / 52c / 16f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["6 oz sirloin steak", "2 medium potatoes, diced and roasted", "1 cup green beans", "1 tbsp butter", "Salt, pepper, garlic powder", "Fresh parsley"], instructions: ["Season steak; sear in cast iron 3–4 min per side for medium.", "Roast potatoes at 400°F with olive oil and seasoning for 20 min.", "Steam green beans; toss with butter.", "Rest steak 5 min before slicing."], tip: "Red meat is the highest source of creatine in food — eat it 2–3x weekly during bulking." },
      { mealType: "Dinner", name: "Salmon & Avocado Rice Bowl", time: "20 min", macros: "44p / 55c / 22f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["7 oz salmon fillet", "1 cup cooked sushi rice", "½ avocado, sliced", "½ cucumber, diced", "2 tbsp soy sauce", "1 tsp sesame oil", "Sesame seeds", "Nori strips (optional)"], instructions: ["Season salmon; bake at 400°F for 12 min or pan-sear 5 min per side.", "Flake over rice with cucumber and avocado.", "Drizzle with soy sauce and sesame oil; garnish."], tip: "Salmon and avocado together provide essential fatty acids critical for muscle growth hormones." },
      { mealType: "Dinner", name: "Pesto Chicken Pasta", time: "25 min", macros: "48p / 65c / 18f", dietary: ["NF", "SF"], ingredients: ["6 oz chicken breast", "4 oz whole wheat penne (dry)", "3 tbsp basil pesto", "1 cup cherry tomatoes, halved", "2 tbsp Parmesan cheese", "1 cup baby spinach", "Salt and pepper"], instructions: ["Cook pasta; reserve ¼ cup pasta water.", "Season and grill chicken; slice.", "Toss pasta with pesto and pasta water.", "Add spinach, tomatoes, and chicken.", "Top with Parmesan."], tip: "Whole wheat pasta provides complex carbs + extra fiber for sustained energy." },
      { mealType: "Dinner", name: "High-Protein Beef Burrito", time: "20 min", macros: "52p / 68c / 18f", dietary: ["NF", "SF"], ingredients: ["6 oz lean ground beef (90%)", "1 large whole wheat tortilla", "¾ cup cooked brown rice", "½ cup black beans", "¼ cup shredded cheese", "2 tbsp Greek yogurt (instead of sour cream)", "½ cup salsa", "Lettuce and tomato"], instructions: ["Brown beef with taco seasoning.", "Warm tortilla; layer rice, beans, beef, cheese, and toppings.", "Add Greek yogurt and salsa.", "Fold burrito tightly."], tip: "Greek yogurt provides extra protein over sour cream with less fat." },
      { mealType: "Snack", name: "Whole Milk Protein Shake", time: "3 min", macros: "40p / 28c / 12f", dietary: ["GF", "NF", "SF"], ingredients: ["2 scoops chocolate or vanilla protein powder", "1 cup whole milk", "½ cup water", "Ice"], instructions: ["Blend or shake until combined.", "Drink within 30 min of training."], tip: "Whole milk provides casein protein — a slow-digesting protein ideal before bed." },
      { mealType: "Snack", name: "Rice Cakes with Peanut Butter & Banana", time: "3 min", macros: "8p / 38c / 9f", dietary: ["GF", "DF", "SF", "Vegan"], ingredients: ["3 rice cakes", "3 tbsp peanut butter", "1 banana, sliced"], instructions: ["Spread peanut butter on each rice cake.", "Top with banana slices."], tip: "A simple, calorie-dense snack to hit your surplus — eat between meals." }
