      { mealType: "Lunch", name: "Baked Potato with Chicken & Broccoli", time: "55 min", macros: "36p / 48c / 8f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["2 large russet potatoes", "5 oz grilled chicken, shredded", "1 cup steamed broccoli", "2 tbsp Greek yogurt", "Salt, pepper, garlic powder", "Green onions"], instructions: ["Bake potatoes at 400°F for 45–50 min.", "Slice open; top with chicken, broccoli, Greek yogurt.", "Season and add green onions."], tip: "Greek yogurt replaces sour cream for extra protein — the flavor difference is minimal." },
      { mealType: "Dinner", name: "Herb-Roasted Chicken Thighs & Veggies", time: "40 min", macros: "40p / 22c / 18f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["4 bone-in chicken thighs, skin-on", "1 cup baby potatoes, halved", "1 cup green beans", "1 cup cherry tomatoes", "3 tbsp olive oil", "1 tsp garlic powder", "1 tsp rosemary", "1 tsp thyme", "Salt and pepper"], instructions: ["Preheat oven to 425°F.", "Toss everything with olive oil and herbs.", "Arrange in a single layer; roast 30–35 min until chicken reaches 165°F.", "Serve directly from the pan."], tip: "Chicken thighs stay juicy even when slightly overcooked — much more forgiving than breast." },
      { mealType: "Dinner", name: "Zucchini Noodles with Shrimp & Pesto", time: "20 min", macros: "32p / 14c / 18f", dietary: ["GF", "NF", "SF"], ingredients: ["3 large zucchini, spiralized", "10 oz shrimp, peeled", "3 tbsp basil pesto", "2 garlic cloves, minced", "1 tbsp olive oil", "Cherry tomatoes", "Parmesan shavings"], instructions: ["Sauté garlic in oil 1 min; add shrimp, cook 2–3 min per side.", "Add zucchini noodles; toss 2 min until just tender.", "Remove from heat; stir in pesto and tomatoes.", "Top with Parmesan."], tip: "Don't overcook zucchini noodles — they should have a slight bite, not be mushy." },
      { mealType: "Dinner", name: "Grass-Fed Beef Lettuce Tacos", time: "20 min", macros: "35p / 14c / 16f", dietary: ["GF", "DF", "NF", "SF"], ingredients: ["1 lb lean ground beef", "1 tbsp taco seasoning (check GF on label)", "8 large butter lettuce leaves", "½ cup diced mango or pineapple", "¼ red onion, diced", "Fresh cilantro", "Lime wedges"], instructions: ["Brown ground beef; drain and add taco seasoning with ¼ cup water.", "Spoon into lettuce cups.", "Top with mango, red onion, and cilantro.", "Squeeze lime over each taco."], tip: "Butter lettuce holds up better than iceberg — it won't crack when you bite in." },
      { mealType: "Snack", name: "Rice Cake with Avocado & Everything Bagel", time: "3 min", macros: "3p / 18c / 8f", dietary: ["GF", "DF", "NF", "SF", "Vegan"], ingredients: ["2 rice cakes (plain)", "½ avocado, mashed", "Everything bagel seasoning", "Red pepper flakes"], instructions: ["Mash avocado with salt.", "Spread on rice cakes.", "Sprinkle with everything bagel seasoning and red pepper."], tip: "A naturally gluten-free alternative to avocado toast — just as satisfying." },
      { mealType: "Snack", name: "Trail Mix with Dark Chocolate", time: "2 min", macros: "6p / 24c / 14f", dietary: ["GF", "DF", "SF", "Vegan"], ingredients: ["¼ cup raw almonds", "¼ cup cashews", "2 tbsp dried cranberries (unsweetened)", "2 tbsp dark chocolate chips (70%+)", "1 tbsp pumpkin seeds"], instructions: ["Mix all ingredients in a small container.", "Portion into snack bags for the week."], tip: "Dark chocolate (70%+) provides magnesium and antioxidants — not just a treat." }
